import{_ as a,o as s,c as t,a1 as n}from"./chunks/framework.Ccs17H5l.js";const u=JSON.parse(`{"title":"Le format d'image EIF","description":"","frontmatter":{},"headers":[],"relativePath":"reference/formats/eif.md","filePath":"reference/formats/eif.md"}`),o={name:"reference/formats/eif.md"};function r(l,e,i,d,p,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="le-format-d-image-eif" tabindex="-1">Le format d&#39;image EIF <a class="header-anchor" href="#le-format-d-image-eif" aria-label="Permalink to &quot;Le format d&#39;image EIF&quot;">​</a></h1><p>EIF (<em>Eadkp Image Format</em>) est le format d&#39;image d&#39;eadkp. Un fichier <code>.eif</code> contient les pixels d&#39;une image tels que l&#39;écran les attend, sans compression, ce qui permet de les envoyer à l&#39;écran sans les décoder.</p><h2 id="en-resume" tabindex="-1">En résumé <a class="header-anchor" href="#en-resume" aria-label="Permalink to &quot;En résumé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Caractéristique</th><th>Valeur</th></tr></thead><tbody><tr><td>Extension</td><td><code>.eif</code></td></tr><tr><td>Couleurs</td><td><a href="./rgb565.html">RGB 565</a>, 2 octets par pixel</td></tr><tr><td>Compression</td><td>aucune</td></tr><tr><td>Transparence</td><td>non</td></tr><tr><td>Taille maximale</td><td>65 535 × 65 535 pixels</td></tr><tr><td>Versions</td><td>une seule : <a href="./eif-v1.html">EIF1</a></td></tr></tbody></table><h2 id="d-ou-viennent-les-fichiers-eif" tabindex="-1">D&#39;où viennent les fichiers <code>.eif</code> <a class="header-anchor" href="#d-ou-viennent-les-fichiers-eif" aria-label="Permalink to &quot;D&#39;où viennent les fichiers \`.eif\`&quot;">​</a></h2><p>On ne les écrit pas à la main. À la compilation, eadkp (<a href="https://github.com/Oignontom8283/eadkp/blob/dev/src/builder.rs" target="_blank" rel="noreferrer">builder.rs</a>) convertit chaque <code>.png</code> du dossier <code>assets/</code> de ton projet :</p><ul><li><code>assets/pain.png</code> devient <code>pain.png.eif</code>, rangé dans le dossier de sortie de Cargo ;</li><li>seuls les <code>.png</code> placés directement dans <code>assets/</code> sont convertis (pas dans un sous-dossier) ;</li><li><code>assets/icon.png</code> est à part : c&#39;est l&#39;icône de l&#39;application, qui doit faire exactement 55 × 56 pixels et suit un autre format (<code>.nwi</code>), pas EIF.</li></ul><h2 id="l-utiliser-dans-une-application" tabindex="-1">L&#39;utiliser dans une application <a class="header-anchor" href="#l-utiliser-dans-une-application" aria-label="Permalink to &quot;L&#39;utiliser dans une application&quot;">​</a></h2><p>La macro <code>include_image!</code> inclut le fichier converti dans le programme. <code>ImageLoader</code> le lit et dit s&#39;il est valide.</p><div class="language-rust line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">use</span><span style="color:#4EC9B0;"> eadkp</span><span style="color:#D4D4D4;">::{include_image, </span><span style="color:#4EC9B0;">ImageFormat</span><span style="color:#D4D4D4;">, </span><span style="color:#4EC9B0;">ImageLoader</span><span style="color:#D4D4D4;">, </span><span style="color:#4EC9B0;">Point</span><span style="color:#D4D4D4;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#569CD6;">let</span><span style="color:#9CDCFE;"> image</span><span style="color:#D4D4D4;"> = </span><span style="color:#4EC9B0;">ImageLoader</span><span style="color:#D4D4D4;">::</span><span style="color:#DCDCAA;">from_flash</span><span style="color:#D4D4D4;">(</span><span style="color:#DCDCAA;">include_image!</span><span style="color:#D4D4D4;">(</span><span style="color:#CE9178;">&quot;pain.png&quot;</span><span style="color:#D4D4D4;">))</span></span>
<span class="line"><span style="color:#D4D4D4;">    .</span><span style="color:#DCDCAA;">expect</span><span style="color:#D4D4D4;">(</span><span style="color:#CE9178;">&quot;image EIF invalide&quot;</span><span style="color:#D4D4D4;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#9CDCFE;">image</span><span style="color:#D4D4D4;">.</span><span style="color:#DCDCAA;">draw</span><span style="color:#D4D4D4;">(</span><span style="color:#4EC9B0;">Point</span><span style="color:#D4D4D4;"> { </span><span style="color:#9CDCFE;">x</span><span style="color:#D4D4D4;">: </span><span style="color:#B5CEA8;">10</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">y</span><span style="color:#D4D4D4;">: </span><span style="color:#B5CEA8;">10</span><span style="color:#D4D4D4;"> });</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Deux façons de charger l&#39;image, selon la manière dont on s&#39;en sert :</p><table tabindex="0"><thead><tr><th>Fonction</th><th>Où sont les pixels</th><th>Lecture</th><th>Convient à</th></tr></thead><tbody><tr><td><code>from_flash</code></td><td>restent dans la mémoire flash</td><td>plus lente</td><td>grands décors, peu redessinés</td></tr><tr><td><code>from_ram</code></td><td>copiés en RAM</td><td>rapide</td><td>sprites, animations</td></tr></tbody></table><p>La copie en RAM coûte la taille de l&#39;image : une image plein écran (320 × 240) prend 153 608 octets, soit environ 150 Kio, sur une RAM d&#39;environ 256 Kio. À réserver aux images petites ou très utilisées.</p><h2 id="comment-le-format-est-reconnu" tabindex="-1">Comment le format est reconnu <a class="header-anchor" href="#comment-le-format-est-reconnu" aria-label="Permalink to &quot;Comment le format est reconnu&quot;">​</a></h2><p>Les quatre premiers octets d&#39;un fichier EIF forment l&#39;identifiant de sa version (<code>EIF1</code> pour la version 1). <code>ImageLoader</code> les lit pour savoir comment interpréter la suite. Si l&#39;identifiant est inconnu, il renvoie <code>ImageError::UnsupportedFormat</code> ; si le fichier fait moins de 8 octets, il renvoie <code>ImageError::CorruptedData</code>.</p><p>Le code est dans <a href="https://github.com/Oignontom8283/eadkp/blob/dev/src/image.rs" target="_blank" rel="noreferrer">image.rs</a>.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./eif-v1.html">EIF1 : la version 1, octet par octet</a></li><li><a href="./rgb565.html">Le format de couleur RGB 565</a></li><li><a href="./../../tool/image-resizing.html">Redimensionner une image avant de l&#39;ajouter</a></li></ul>`,18)])])}const h=a(o,[["render",r]]);export{u as __pageData,h as default};
